fn main() -> Void {
    let cap: Int[] = [4, 3, 6, 2, 5];
    let s: Int[] = [2, 3, 1, 4];
    let n: Int = length(s);
    let total: Int = 1 << n;
    let skippable: Int = 0;
    let maxDelivered: Int = 0;

    loop mask in 0..total {
        let rem: Int[] = [cap[0], cap[1], cap[2], cap[3], cap[4]];
        let ok: Bool = true;
        let delivered: Int = 0;
        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                continue;
            }
            let placed: Bool = false;
            loop b in i..5 {
                if rem[b] >= s[i] {
                    rem[b] = rem[b] - s[i];
                    placed = true;
                    break;
                }
            }
            if !placed {
                ok = false;
                break;
            }
            delivered = delivered + 1;
        }
        if ok {
            skippable = skippable + 1;
            if delivered > maxDelivered {
                maxDelivered = delivered;
            }
        }
    }

    fx {
        println("Skippable subsets: ", skippable);
        println("Max shipments delivered: ", maxDelivered);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [3, 1, 4, 1, 5],
        [2, 7, 1, 8, 2],
        [6, 1, 5, 9, 3],
        [4, 8, 2, 6, 4]
    ];

    let rows: Int = 4;
    let cols: Int = 5;

    let count: Int[][] = [];
    let best: Int[][] = [];

    loop r in 0..rows {
        let cRow: Int[] = [];
        let bRow: Int[] = [];
        loop c in 0..cols {
            cRow = cRow + [0];
            bRow = bRow + [0];
        }
        count = count + [cRow];
        best = best + [bRow];
    }

    count[0][0] = 1;
    best[0][0] = grid[0][0];

    loop r in 0..rows {
        loop c in 0..cols {
            if r == 0 && c == 0 {
                continue;
            }
            let cnt: Int = 0;
            let mx: Int = 0;
            if c > 0 {
                cnt = cnt + count[r][c - 1];
                let cand: Int = best[r][c - 1] + grid[r][c];
                if cand > mx {
                    mx = cand;
                }
            }
            if r > 0 {
                cnt = cnt + count[r - 1][c];
                let cand: Int = best[r - 1][c] + grid[r][c];
                if cand > mx {
                    mx = cand;
                }
            }
            if r > 0 && c > 0 {
                cnt = cnt + count[r - 1][c - 1];
                let cand: Int = best[r - 1][c - 1] + grid[r][c];
                if cand > mx {
                    mx = cand;
                }
            }
            count[r][c] = cnt;
            best[r][c] = mx;
        }
    }

    fx {
        println("Paths: ", count[rows - 1][cols - 1]);
        println("Max apples on any path: ", best[rows - 1][cols - 1]);
    }
    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [2, 5, 3, 7],
        [4, 1, 6, 2],
        [8, 3, 2, 5]
    ];
    let rows: Int = 3;
    let cols: Int = 4;
    let paths: Int[][] = [];
    let best: Int[][] = [];

    loop r in 0..rows {
        let pRow: Int[] = [];
        let bRow: Int[] = [];
        loop c in 0..cols {
            if r == 0 && c == 0 {
                pRow = pRow + [1];
                bRow = bRow + [grid[0][0]];
            } else if r == 0 {
                pRow = pRow + [pRow[c - 1]];
                bRow = bRow + [bRow[c - 1] + grid[r][c]];
            } else if c == 0 {
                pRow = pRow + [paths[r - 1][c]];
                bRow = bRow + [best[r - 1][c] + grid[r][c]];
            } else {
                pRow = pRow + [paths[r - 1][c] + pRow[c - 1]];
                bRow = bRow + [max(best[r - 1][c], bRow[c - 1]) + grid[r][c]];
            }
        }
        paths = paths + [pRow];
        best = best + [bRow];
    }

    fx {
        println("Paths: ", paths[rows - 1][cols - 1]);
        println("Best honey: ", best[rows - 1][cols - 1], " jars");
    }
    ret;
}

fn main() -> Void {
    let total: Int = 0;
    let withAfull: Int = 0;

    loop a in 0..4 {
        loop b in 0..a + 1 {
            loop c in 0..b + 1 {
                loop d in 0..c + 1 {
                    let e: Int = 7 - a - b - c - d;
                    if e >= 0 && e <= 3 && e <= d {
                        total = total + 1;
                        if a == 3 {
                            withAfull = withAfull + 1;
                        }
                    }
                }
            }
        }
    }

    fx {
        println("Distributions: ", total);
        println("Distributions with shelf A full: ", withAfull);
    }
    ret;
}

fn main() -> Void {
    let tips: Int[] = [12, 7, 15, 9, 11, 8];
    let n: Int = length(tips);
    let limit: Int = 30;

    let maxDays: Int = 0;
    let ways: Int = 0;

    loop mask in 0..(1 << n) {
        let running: Int = 0;
        let count: Int = 0;
        let ok: Bool = true;
        loop i in 0..n {
            if (mask & (1 << i)) != 0 {
                running = running + tips[i];
                count = count + 1;
                if running > limit {
                    ok = false;
                    break;
                }
            }
        }
        if ok {
            if count > maxDays {
                maxDays = count;
                ways = 1;
            } else if count == maxDays {
                ways = ways + 1;
            }
        }
    }

    fx {
        println("Max days: ", maxDays);
        println("Ways: ", ways);
    }
    ret;
}

