fn main() -> Void {
    let board: Int[] = [1, 3, 5, 6];
    let alight: Int[] = [4, 5, 7, 7];
    let n: Int = length(board);
    let express: Int = 0;
    let peak: Int = 0;
    let current: Int = 0;

    loop i in 0..n {
        if alight[i] - board[i] >= 4 {
            express = express + 1;
        }
    }

    loop stop in 1..8 {
        loop i in 0..n {
            if board[i] == stop {
                current = current + 1;
            }
            if alight[i] == stop {
                current = current - 1;
            }
        }
        if current > peak {
            peak = current;
        }
    }

    fx {
        println("Express passengers: ", express);
        println("Peak riders: ", peak);
    }
    ret;
}

