fn main() -> Void {
    let grid: Text[][] = [
        ["G", "R"],
        ["R", "G"]
    ];
    let rows: Int = 2;
    let cols: Int = 2;
    let rounds: Int = 3;

    loop r in 0..rounds {
        let newGrid: Text[][] = [];
        loop i in 0..rows {
            let row: Text[] = [];
            loop j in 0..cols {
                let greenCount: Int = 0;
                if i > 0 {
                    if grid[i - 1][j] == "G" {
                        greenCount = greenCount + 1;
                    }
                }
                if i < rows - 1 {
                    if grid[i + 1][j] == "G" {
                        greenCount = greenCount + 1;
                    }
                }
                if j > 0 {
                    if grid[i][j - 1] == "G" {
                        greenCount = greenCount + 1;
                    }
                }
                if j < cols - 1 {
                    if grid[i][j + 1] == "G" {
                        greenCount = greenCount + 1;
                    }
                }
                if greenCount >= 2 {
                    row = row + ["G"];
                } else {
                    row = row + [grid[i][j]];
                }
            }
            newGrid = newGrid + [row];
        }
        grid = newGrid;
    }

    let totalGreen: Int = 0;
    loop i in 0..rows {
        loop j in 0..cols {
            if grid[i][j] == "G" {
                totalGreen = totalGreen + 1;
            }
        }
    }

    fx {
        loop i in 0..rows {
            loop j in 0..cols {
                if j > 0 {
                    print(" ");
                }
                print(grid[i][j]);
            }
            println("");
        }
        println("GREEN count: ", totalGreen);
    }
    ret;
}

