@pure
fn isPrime(n: Int) -> Bool {
    if n < 2 {
        ret false;
    }
    if n == 2 {
        ret true;
    }
    if n % 2 == 0 {
        ret false;
    }
    let d: Int = 3;
    loop d * d <= n {
        if n % d == 0 {
            ret false;
        }
        d = d + 2;
    }
    ret true;
}

@pure
fn isIncreasing(n: Int) -> Bool {
    let s: Text = int_to_text(n);
    let len: Int = string_len(s);
    if len <= 1 {
        ret true;
    }
    loop i in 1..len {
        if ord(s[i]) <= ord(s[i - 1]) {
            ret false;
        }
    }
    ret true;
}

fn main() -> Void {
    let nums: Int[] = [137, 246, 357, 481, 571, 631, 727, 829];
    let primeCount: Int = 0;
    let incCount: Int = 0;

    loop i in 0..length(nums) {
        let n: Int = nums[i];
        let p: Bool = isPrime(n);
        let inc: Bool = isIncreasing(n);
        if p {
            primeCount = primeCount + 1;
        }
        if inc {
            incCount = incCount + 1;
        }
        let pLabel: Text = if p { "PRIME" } else { "COMPOSITE" };
        let iLabel: Text = if inc { "INCREASING" } else { "NOT INCREASING" };
        fx {
            println(int_to_text(n), ": ", pLabel, ", ", iLabel);
        }
    }

    fx {
        println("COUNT: ", primeCount, " primes, ", incCount, " increasing");
    }
    ret;
}

@pure
fn octalToDecimal(s: Text) -> Int {
    let result: Int = 0;
    loop i in 0..string_len(s) {
        let digit: Int = ord(s[i]) - 48;
        result = result * 8 + digit;
    }
    ret result;
}

fn main() -> Void {
    let serials: Text[] = ["147", "256", "371", "404", "513", "622", "731"];
    let divisibleCount: Int = 0;

    loop i in 0..length(serials) {
        let octal: Text = serials[i];
        let decimal: Int = octalToDecimal(octal);
        let divisible: Bool = decimal % 9 == 0;
        if divisible {
            divisibleCount = divisibleCount + 1;
        }
        let verdict: Text = if divisible { "YES" } else { "NO" };
        fx {
            println("OCTAL ", octal, " = DECIMAL ", decimal, ", DIVISIBLE BY 9: ", verdict);
        }
    }

    fx {
        println("DIVISIBLE COUNT: ", divisibleCount);
    }
    ret;
}

fn main() -> Void {
    let codes: Text[] = ["0123456789", "1111111111", "2000000001", "3141592653", "4242424242"];
    let validCount: Int = 0;

    loop ci in 0..length(codes) {
        let code: Text = codes[ci];
        let sum: Int = 0;
        loop i in 0..10 {
            let d: Int = ord(code[i]) - 48;
            let w: Int = 10 - i;
            sum = sum + d * w;
        }
        let status: Text = if sum % 11 == 0 { "VALID" } else { "INVALID" };
        if sum % 11 == 0 {
            validCount = validCount + 1;
        }
        fx {
            println(code, ": ", status, " (weighted sum = ", sum, ")");
        }
    }

    fx {
        println("VALID COUNT: ", validCount);
    }
    ret;
}

@pure
fn countDivisors(n: Int) -> Int {
    let count: Int = 0;
    loop i in 1..n + 1 {
        if n % i == 0 {
            count = count + 1;
        }
    }
    ret count;
}

@pure
fn isPerfectSquare(n: Int) -> Bool {
    if n < 0 {
        ret false;
    }
    let r: Int = int(sqrt(real(n)));
    ret r * r == n;
}

fn main() -> Void {
    let caps: Int[] = [16, 27, 36, 48, 64, 75];
    let squareCount: Int = 0;

    loop i in 0..length(caps) {
        let c: Int = caps[i];
        let d: Int = countDivisors(c);
        let sq: Bool = isPerfectSquare(c);
        if sq {
            squareCount = squareCount + 1;
        }
        let label: Text = if sq { "SQUARE" } else { "NOT SQUARE" };
        fx {
            println("Room with capacity ", c, ": ", d, " divisors, ", label);
        }
    }

    fx {
        println("SQUARE ROOMS: ", squareCount);
    }
    ret;
}

fn main() -> Void {
    let readings: Int[] = [41, 17, 52, 28, 63, 39, 74, 50, 85, 61, 96, 72];
    let counts: Int[] = [0, 0, 0, 0, 0, 0];

    loop i in 0..length(readings) {
        let r: Int = readings[i] % 6;
        counts[r] = counts[r] + 1;
        let num: Int = i + 1;
        let numText: Text = int_to_text(num);
        let padded: Text = "";
        if num < 10 {
            padded = "00" + numText;
        } else if num < 100 {
            padded = "0" + numText;
        } else {
            padded = numText;
        }
        fx {
            println("Reading ", padded, ": remainder ", r, " when divided by 6");
        }
    }

    let bestR: Int = 0;
    let bestC: Int = counts[0];
    loop r in 1..6 {
        if counts[r] > bestC {
            bestC = counts[r];
            bestR = r;
        }
    }

    fx {
        println("MOST COMMON REMAINDER: ", bestR, " (appears ", bestC, " times)");
    }
    ret;
}

@pure
fn reverseNum(n: Int) -> Int {
    let r: Int = 0;
    let x: Int = n;
    loop x > 0 {
        r = r * 10 + x % 10;
        x = x div 10;
    }
    ret r;
}

fn main() -> Void {
    let fares: Int[] = [123, 456, 789, 100, 246, 357, 480];
    let diffCount: Int = 0;
    let bothCount: Int = 0;

    loop i in 0..length(fares) {
        let f: Int = fares[i];
        let r: Int = reverseNum(f);
        let diff: Bool = r != f;
        let both: Bool = (f % 3 == 0) && (r % 3 == 0);
        if diff {
            diffCount = diffCount + 1;
        }
        if both {
            bothCount = bothCount + 1;
        }
        let diffStr: Text = if diff { "YES" } else { "NO" };
        let bothStr: Text = if both { "YES" } else { "NO" };
        fx {
            println("Fare ", f, ": reverse ", r, ", REVERSED DIFFERENT: ", diffStr, ", BOTH DIV BY 3: ", bothStr);
        }
    }

    fx {
        println("COUNT: ", diffCount, " different, ", bothCount, " both divisible");
    }
    ret;
}

fn main() -> Void {
