type Track {
    name: Text = "";
    dur: Text = "";
}

@pure
fn parseDur(d: Text) -> Int {
    let colon: Int = pos(":", d);
    let mm: Int = parse_int(d[0..colon]);
    let ss: Int = parse_int(d[colon + 1..string_len(d)]);
    ret mm * 60 + ss;
}

fn main() -> Void {
    let tracks: Track[] = [
        new Track { name: "Horizon", dur: "03:45" },
        new Track { name: "Nebula", dur: "04:12" },
        new Track { name: "Cascade", dur: "02:58" },
        new Track { name: "Ember", dur: "05:30" },
        new Track { name: "Drift", dur: "03:07" },
        new Track { name: "Solace", dur: "04:48" },
        new Track { name: "Prism", dur: "02:41" },
        new Track { name: "Vortex", dur: "06:15" }
    ];

    let count: Int = length(tracks);
    let totalSecs: Int = 0;
    let over4: Int = 0;
    let shortestName: Text = tracks[0].name;
    let longestName: Text = tracks[0].name;
    let shortestSecs: Int = parseDur(tracks[0].dur);
    let longestSecs: Int = parseDur(tracks[0].dur);
    let cdeCount: Int = 0;

    loop i in 0..count {
        let secs: Int = parseDur(tracks[i].dur);
        totalSecs = totalSecs + secs;
        if secs > 240 {
            over4 = over4 + 1;
        }
        if secs < shortestSecs {
            shortestSecs = secs;
            shortestName = tracks[i].name;
        }
        if secs > longestSecs {
            longestSecs = secs;
            longestName = tracks[i].name;
        }
        let first: Text = tracks[i].name[0];
        if first == "C" || first == "D" || first == "E" {
            cdeCount = cdeCount + 1;
        }
    }

    let totalMin: Int = totalSecs div 60;
    let totalRem: Int = totalSecs % 60;
    let avg: Real = totalSecs * 1.0 / count;

    fx {
        println("Tracks: ", count);
        println("Total duration: ", totalMin, ":", int_to_text(totalRem));
        println("Tracks over 4 minutes: ", over4);
        println("Shortest track: ", shortestName);
        println("Longest track: ", longestName);
        println("Average duration in seconds: ", formatfloat(avg, 2));
        println("Tracks starting with letter C or D or E: ", cdeCount);
    }
    ret;
}

