fn main() -> Void {
    let pos: Int = 0;
    let carrying: Bool = false;
    let drops: Int = 0;

    let cmds: Text[] = ["MOVE 3", "PICKUP", "MOVE -1", "DROP", "MOVE 4", "PICKUP", "MOVE -2", "DROP"];

    loop i in 0..length(cmds) {
        let cmd: Text = cmds[i];
        if cmd == "PICKUP" {
            if !carrying {
                carrying = true;
            }
        } else if cmd == "DROP" {
            if carrying {
                carrying = false;
                drops = drops + 1;
                fx {
                    println("DROPPED at square ", pos, " with total drops ", drops);
                }
            }
        } else {
            let parts: Text[] = split(cmd, " ");
            let n: Int = parse_int(parts[1]);
            pos = pos + n;
            if pos < 0 {
                pos = 0;
            }
            if pos > 9 {
                pos = 9;
            }
        }
    }

    let c: Int = 0;
    if carrying {
        c = 1;
    }
    fx {
        println("FINAL position ", pos, " carrying ", c);
    }
    ret;
}

