fn main() -> Void {
    let ring: Text[] = ["", "", "", "", ""];
    let head: Int = 0;
    let tail: Int = 0;
    let count: Int = 0;

    let ops: Text[] = ["IN A1", "IN A2", "OUT", "IN A3", "OUT", "IN A4", "IN A5", "IN A6", "OUT", "IN A7", "OUT", "OUT", "OUT", "OUT"];

    loop i in 0..length(ops) {
        let op: Text = ops[i];
        if op == "OUT" {
            if count == 0 {
                fx {
                    println("DISPENSED NONE count 0");
                }
            } else {
                let item: Text = ring[head];
                ring[head] = "";
                head = (head + 1) % 5;
                count = count - 1;
                fx {
                    println("DISPENSED ", item, " count ", count);
                }
            }
        } else {
            if count < 5 {
                let item: Text = op[3..5];
                ring[tail] = item;
                tail = (tail + 1) % 5;
                count = count + 1;
            }
        }
    }

    let headItem: Text = "NONE";
    if count > 0 {
        headItem = ring[head];
    }

    fx {
        println("RING count ", count, " head ", headItem);
    }

    ret;
}

