fn main() -> Void {
    let stationDist: Real[] = [5.0, 15.0, 25.0];
    let cups: Int[] = [40, 30, 25];
    let speeds: Real[] = [0.25, 0.20, 0.30, 0.22];
    let needs: Int[][] = [
        [1, 2, 1],
        [2, 1, 2],
        [1, 1, 1],
        [2, 2, 1]
    ];

    let nRunners: Int = 4;
    let nStations: Int = 3;

    let times: Real[][] = [];
    loop r in 0..nRunners {
        let row: Real[] = [];
        loop s in 0..nStations {
            row = row + [stationDist[s] / speeds[r]];
        }
        times = times + [row];
    }

    let order: Int[] = [0, 1, 2, 3];
    loop i in 1..nRunners {
        let v: Int = order[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if order[j] <= v {
                break;
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = v;
    }

    let events: Int[] = [];
    loop i in 0..nRunners {
        loop s in 0..nStations {
            events = events + [i * nStations + s];
        }
    }

    loop i in 1..length(events) {
        let v: Int = events[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let evA: Int = events[j];
            let evB: Int = v;
            let rA: Int = evA div nStations;
            let sA: Int = evA % nStations;
            let rB: Int = evB div nStations;
            let sB: Int = evB % nStations;
            let tA: Real = times[rA][sA];
            let tB: Real = times[rB][sB];
            if tA < tB {
                break;
            }
            if tA == tB && rA <= rB {
                break;
            }
            events[j + 1] = events[j];
            j = j - 1;
        }
        events[j + 1] = v;
    }

    loop i in 0..length(events) {
        let ev: Int = events[i];
        let r: Int = ev div nStations;
        let s: Int = ev % nStations;
        let need: Int = needs[r][s];
        let take: Int = min(need, cups[s]);
        cups[s] = cups[s] - take;
    }

    fx {
        println("Station 1 remaining ", cups[0]);
        println("Station 2 remaining ", cups[1]);
        println("Station 3 remaining ", cups[2]);
    }
    ret;
}

fn main() -> Void {
    let p1: Int = 300;
    let p2: Int = 300;
    let times: Int[] = [45, 55, 60, 80, 90, 70, 75, 100, 50, 65, 120, 40];
    let moveNum: Int = 0;
    let stopped: Bool = false;

    loop i in 0..length(times) {
        if stopped {
            break;
        }
        moveNum = moveNum + 1;
        let t: Int = times[i];
        if moveNum % 2 == 1 {
            p1 = p1 - t;
        } else {
            p2 = p2 - t;
        }
        let showP1: Int = p1;
        let showP2: Int = p2;
        if showP1 < 0 {
            showP1 = 0;
        }
        if showP2 < 0 {
            showP2 = 0;
        }
        fx {
            println("Move ", moveNum, " P1 ", showP1, " P2 ", showP2);
        }
        if p1 <= 0 || p2 <= 0 {
            stopped = true;
        }
    }
    ret;
}

fn main() -> Void {
    let arrive: Int[] = [0, 5, 10, 25, 45];
    let dry: Int[] = [40, 30, 50, 20, 35];
    let free1: Int = 0;
    let free2: Int = 0;

    loop i in 0..length(arrive) {
        let a: Int = arrive[i];
        let d: Int = dry[i];
        let dryer: Int = 0;
        let start: Int = 0;
        let finish: Int = 0;

        if a >= free1 {
            dryer = 1;
            start = a;
            finish = a + d;
            free1 = finish;
        } else if a >= free2 {
            dryer = 2;
            start = a;
            finish = a + d;
            free2 = finish;
        } else {
            if free1 <= free2 {
                dryer = 1;
                start = free1;
                finish = free1 + d;
                free1 = finish;
            } else {
                dryer = 2;
                start = free2;
                finish = free2 + d;
                free2 = finish;
            }
        }

        fx {
            println("Load ", i + 1, " dryer ", dryer, " start ", start, " finish ", finish);
        }
    }

    ret;
}

