                shelfValue = shelfValue + row[c] * 0.10;
            } else {
                shelfValue = shelfValue + row[c] * 0.25;
            }
        }
        shelfValues[r] = shelfValue;
        grandTotal = grandTotal + shelfValue;
    }

    fx {
        println("Coin Levels");
        loop r in 0..4 {
            let row: Int[] = table[r];
            println(row[0], " ", row[1], " ", row[2]);
        }
        println("Column Totals: ", colTotals[0], " ", colTotals[1], " ", colTotals[2]);
        println("Shelf Value: ", formatfloat(shelfValues[0], 2), " ", formatfloat(shelfValues[1], 2), " ", formatfloat(shelfValues[2], 2), " ", formatfloat(shelfValues[3], 2));
