fn main() -> Void {
    let p1: Real[][] = [[18.5, 19.2, 20.1], [17.8, 18.9, 19.5]];
    let p2: Real[][] = [[21.3, 22.0, 21.7], [20.5, 21.1, 22.4]];
    let p3: Real[][] = [[16.2, 17.0, 16.8], [15.9, 16.5, 17.3]];
    let p4: Real[][] = [[19.8, 20.6, 21.2], [19.1, 20.0, 20.8]];

    let plots: Real[][][] = [p1, p2, p3, p4];

    let avg1: Real = (18.5 + 19.2 + 20.1 + 17.8 + 18.9 + 19.5) / 6.0;
    let avg2: Real = (21.3 + 22.0 + 21.7 + 20.5 + 21.1 + 22.4) / 6.0;
    let avg3: Real = (16.2 + 17.0 + 16.8 + 15.9 + 16.5 + 17.3) / 6.0;
    let avg4: Real = (19.8 + 20.6 + 21.2 + 19.1 + 20.0 + 20.8) / 6.0;

    let avgs: Real[] = [avg1, avg2, avg3, avg4];

    let hottest: Real = 0.0;
    let coldest: Real = 0.0;
    let first: Bool = true;

    loop p in 0..length(plots) {
        loop r in 0..length(plots[p]) {
            loop c in 0..length(plots[p][r]) {
                let v: Real = plots[p][r][c];
                if first {
                    hottest = v;
                    coldest = v;
                    first = false;
                } else {
                    if v > hottest {
                        hottest = v;
                    }
                    if v < coldest {
                        coldest = v;
                    }
                }
            }
        }
    }

    let warmestIdx: Int = 0;
    loop i in 1..length(avgs) {
        if avgs[i] > avgs[warmestIdx] {
            warmestIdx = i;
        }
    }

    fx {
        println("Garden Temps");
        println("Plot 1 Avg: ", formatfloat(avgs[0], 1));
        println("Plot 2 Avg: ", formatfloat(avgs[1], 1));
        println("Plot 3 Avg: ", formatfloat(avgs[2], 1));
        println("Plot 4 Avg: ", formatfloat(avgs[3], 1));
        println("Hottest Sensor: ", formatfloat(hottest, 1));
        println("Coldest Sensor: ", formatfloat(coldest, 1));
        println("Warmest Plot: ", warmestIdx + 1);
    }
    ret;
}

fn main() -> Void {
    let delays: Int[][] = [
        [0, 2, 1, 3],
        [1, 0, 4, 2],
        [2, 1, 0, 5],
        [3, 2, 1, 0]
    ];

    let maxDelay: Int = 0;
    let onTime: Int = 0;
    let worstStation: Int = 1;
    let worstTotal: Int = 0;

    loop r in 0..length(delays) {
        let rowTotal: Int = 0;
        loop c in 0..length(delays[r]) {
            let v: Int = delays[r][c];
            if v > maxDelay {
                maxDelay = v;
            }
            if v == 0 {
                onTime = onTime + 1;
            }
            rowTotal = rowTotal + v;
        }
        if r == 0 || rowTotal > worstTotal {
            worstTotal = rowTotal;
            worstStation = r + 1;
        }
    }

    fx {
        println("Train Delays");
        loop r in 0..length(delays) {
            let line: Text = "Station " + int_to_text(r + 1) + ":";
            loop c in 0..length(delays[r]) {
                line = line + " " + int_to_text(delays[r][c]);
            }
            println(line);
        }
        println("Max Delay: ", maxDelay, " min");
        println("On-Time Slots: ", onTime);
        println("Worst Station: ", worstStation);
    }
    ret;
}

