    loop i in 1..n {
        let keyName: Text = names[i];
        let keyQty: Int = qtys[i];
        let j: Int = i - 1;
        loop j >= 0 {
            let before: Bool = false;
            if qtys[j] < keyQty {
                before = true;
            } else if qtys[j] == keyQty && names[j] < keyName {
                before = true;
            }
            if before {
                break;
            }
            names[j + 1] = names[j];
            qtys[j + 1] = qtys[j];
            j = j - 1;
        }
        names[j + 1] = keyName;
        qtys[j + 1] = keyQty;
    }

    fx {
        loop i in 0..n {
            println(names[i], " ", qtys[i]);
        }
    }
    ret;
}

@pure
fn sorted(xs: Int[]) -> Int[] {
    let out: Int[] = xs;
    loop i in 1..length(out) {
        let v: Int = out[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if out[j] <= v {
                break;
            }
            out[j + 1] = out[j];
            j = j - 1;
        }
        out[j + 1] = v;
    }
    ret out;
}

