fn main() -> Void {
    let blocked: Bool[][] = [];
    loop r in 0..4 {
        let row: Bool[] = [];
        loop c in 0..4 {
            let b: Bool = false;
            if (r == 1 && c == 1) || (r == 1 && c == 2) || (r == 2 && c == 2) {
                b = true;
            }
            row = row + [b];
        }
        blocked = blocked + [row];
    }

    let cost: Int[][] = [];
    let count: Int[][] = [];
    loop r in 0..4 {
        let crow: Int[] = [];
        let ccount: Int[] = [];
        loop c in 0..4 {
            crow = crow + [999999];
            ccount = ccount + [0];
        }
        cost = cost + [crow];
        count = count + [ccount];
    }

    if !blocked[0][0] {
        cost[0][0] = 1;
        count[0][0] = 1;
    }

    loop r in 0..4 {
        loop c in 0..4 {
            if r == 0 && c == 0 {
                continue;
            }
            if blocked[r][c] {
                continue;
            }
            let best: Int = 999999;
            let ways: Int = 0;
            if r > 0 && !blocked[r - 1][c] {
                if cost[r - 1][c] < best {
                    best = cost[r - 1][c];
                    ways = count[r - 1][c];
                } else if cost[r - 1][c] == best {
                    ways = ways + count[r - 1][c];
                }
            }
            if c > 0 && !blocked[r][c - 1] {
                if cost[r][c - 1] < best {
                    best = cost[r][c - 1];
                    ways = count[r][c - 1];
                } else if cost[r][c - 1] == best {
                    ways = ways + count[r][c - 1];
                }
            }
            if best < 999999 {
                cost[r][c] = best + 1;
                count[r][c] = ways;
            }
        }
    }

    fx {
        println("Minimal cost paths: ", count[3][3]);
    }
    ret;
}

