    let n: Int = length(carbons);

    let balanced: Int = 0;
    let highest: Real = 0.0;
    let lowest: Real = 0.0;
    let idealIdx: Int = 0;
    let idealDist: Real = 0.0;

    loop i in 0..n {
        let ratio: Real = carbons[i] * 1.0 / nitrogens[i];
        if ratio >= 20.0 && ratio <= 30.0 {
            balanced = balanced + 1;
        }
        if i == 0 {
            highest = ratio;
            lowest = ratio;
            idealIdx = 0;
            idealDist = abs(ratio - 25.0);
        } else {
            if ratio > highest {
                highest = ratio;
            }
            if ratio < lowest {
                lowest = ratio;
            }
            let d: Real = abs(ratio - 25.0);
            if d < idealDist {
                idealDist = d;
                idealIdx = i;
            }
        }
    }

    fx {
        println("Batches: ", n);
        println("Balanced: ", balanced);
        println("Highest Ratio: ", formatfloat(highest, 2));
        println("Lowest Ratio: ", formatfloat(lowest, 2));
        println("Ideal Batch: ", idealIdx + 1);
    }
    ret;
}

