@pure
fn toBase7(n: Int) -> Text {
    if n == 0 {
        ret "0";
    }
    let digits: Int[] = [];
    let v: Int = n;
    loop v > 0 {
        digits = digits + [v % 7];
        v = v div 7;
    }
    let out: Text = "";
    loop i in 0..length(digits) {
        out = out + int_to_text(digits[length(digits) - 1 - i]);
    }
    ret out;
}

