fn main() -> Void {
    let grid: Int[][] = [
        [0, 0, 1, 0],
        [1, 0, 0, 0],
        [0, 0, 1, 1],
        [0, 1, 0, 0]
    ];

    let dp: Int[][] = [];
    loop r in 0..4 {
        let row: Int[] = [];
        loop c in 0..4 {
            row = row + [0];
        }
        dp = dp + [row];
    }

    if grid[0][0] == 0 {
        dp[0][0] = 1;
    }

    loop r in 0..4 {
        loop c in 0..4 {
            if r == 0 && c == 0 {
                continue;
            }
            if grid[r][c] == 1 {
                dp[r][c] = 0;
            } else {
                let ways: Int = 0;
                if r > 0 {
                    ways = ways + dp[r - 1][c];
                }
                if c > 0 {
                    ways = ways + dp[r][c - 1];
                }
                dp[r][c] = ways;
            }
        }
    }

    fx {
        println("Paths: ", dp[3][3]);
    }
    ret;
}

