fn main() -> Void {
    let names: Text[] = ["Pushup", "Situp", "Squat", "Lunge", "PlankSec", "Burpee"];
    let reps: Int[] = [32, 45, 32, 18, 45, 12];
    let n: Int = length(reps);

    // Collect distinct rep values
    let distinct: Int[] = [];
    loop i in 0..n {
        let found: Bool = false;
        loop j in 0..length(distinct) {
            if distinct[j] == reps[i] {
                found = true;
            }
        }
        if !found {
            distinct = distinct + [reps[i]];
        }
    }

    // Sort distinct in descending order (insertion sort)
    let d: Int = length(distinct);
    loop i in 1..d {
        let v: Int = distinct[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if distinct[j] >= v {
                break;
            }
            distinct[j + 1] = distinct[j];
            j = j - 1;
        }
        distinct[j + 1] = v;
    }

    // Assign ranks: for each exercise, find its rep's position in sorted distinct
    loop i in 0..n {
        let rank: Int = 1;
        loop k in 0..d {
            if distinct[k] == reps[i] {
                rank = k + 1;
            }
        }
        fx {
            println(names[i], " = ", rank);
        }
    }
    ret;
}

