fn countDistinctLess(paces: Real[], target: Real) -> Int {
    let count: Int = 0;
    loop i in 0..length(paces) {
        if paces[i] < target {
            // Check if this pace is already counted (i.e., appears earlier)
            let already: Bool = false;
            loop j in 0..i {
                if paces[j] == paces[i] {
                    already = true;
                    break;
                }
            }
            if !already {
                count = count + 1;
            }
        }
