fn fmtTime(m: Int) -> Text {
    let h: Int = m div 60;
    let mm: Int = m % 60;
    let hs: Text = int_to_text(h);
    let ms: Text = int_to_text(mm);
    let hp: Text = "";
    if string_len(hs) == 1 {
        hp = "0" + hs;
    } else {
        hp = hs;
    }
    let mp: Text = "";
    if string_len(ms) == 1 {
        mp = "0" + ms;
    } else {
        mp = ms;
    }
    ret hp + ":" + mp;
}

