fn main() -> Void {
    let blocked: Bool[][] = [];
    loop r in 0..4 {
        let row: Bool[] = [];
        loop c in 0..4 {
            row = row + [false];
        }
        blocked = blocked + [row];
    }
    blocked[1][1] = true;
    blocked[2][0] = true;
    blocked[1][3] = true;

    let dp: Int[][] = [];
    loop r in 0..4 {
        let row: Int[] = [];
        loop c in 0..4 {
            row = row + [0];
        }
        dp = dp + [row];
    }

    if !blocked[0][0] {
        dp[0][0] = 1;
    }

    loop r in 0..4 {
        loop c in 0..4 {
            if r == 0 && c == 0 {
                continue;
            }
            if blocked[r][c] {
                continue;
            }
            let ways: Int = 0;
            if r > 0 {
                ways = ways + dp[r - 1][c];
            }
            if c > 0 {
                ways = ways + dp[r][c - 1];
            }
            dp[r][c] = ways;
        }
    }

    fx {
        println("Paths: ", dp[3][3]);
    }
    ret;
}

