fn main() -> Void {
    let stations: Text[] = ["A", "B", "C", "D", "E"];
    let adj: Text[][] = [
        ["B", "D"],
        ["A", "C"],
        ["B", "E"],
        ["A", "E"],
        ["D", "C"]
    ];
    let visited: Bool[] = [false, false, false, false, false];
    let queue: Int[] = [0];
    visited[0] = true;
    let head: Int = 0;
    loop head < length(queue) {
        let cur: Int = queue[head];
        head = head + 1;
        loop j in 0..length(adj[cur]) {
            let nb: Text = adj[cur][j];
            let ni: Int = 0;
            loop k in 0..length(stations) {
                if stations[k] == nb {
                    ni = k;
                    break;
                }
            }
            if !visited[ni] {
                visited[ni] = true;
                queue = queue + [ni];
            }
        }
    }
    let out: Text = "";
    loop i in 0..length(stations) {
        if visited[i] {
            if out != "" {
                out = out + ",";
            }
            out = out + stations[i];
        }
    }
    fx {
        println("Reachable: ", out);
    }
    ret;
}

