fn main() -> Void {
    let grid: Int[][] = [
        [1, 1, 2, 0],
        [2, 3, 1, 1],
        [0, 1, 2, 2],
        [3, 0, 1, 3]
    ];
    let visited: Bool[][] = [
        [false, false, false, false],
        [false, false, false, false],
        [false, false, false, false],
        [false, false, false, false]
    ];
    let sizes: Int[] = [];
    let emptyCount: Int = 0;

    loop r in 0..4 {
        loop c in 0..4 {
            if grid[r][c] == 0 {
                emptyCount = emptyCount + 1;
            }
        }
    }

    loop r in 0..4 {
        loop c in 0..4 {
            if grid[r][c] == 1 && !visited[r][c] {
                let size: Int = 0;
                let stack: Int[] = [r * 4 + c];
                visited[r][c] = true;
                loop {
                    if length(stack) == 0 {
                        break;
                    }
                    let idx: Int = stack[length(stack) - 1];
                    stack = stack[0..length(stack) - 1];
                    let cr: Int = idx div 4;
                    let cc: Int = idx % 4;
                    size = size + 1;
                    if cr > 0 && !visited[cr - 1][cc] && grid[cr - 1][cc] == 1 {
                        visited[cr - 1][cc] = true;
                        stack = stack + [(cr - 1) * 4 + cc];
                    }
                    if cr < 3 && !visited[cr + 1][cc] && grid[cr + 1][cc] == 1 {
                        visited[cr + 1][cc] = true;
                        stack = stack + [(cr + 1) * 4 + cc];
                    }
                    if cc > 0 && !visited[cr][cc - 1] && grid[cr][cc - 1] == 1 {
                        visited[cr][cc - 1] = true;
                        stack = stack + [cr * 4 + (cc - 1)];
                    }
                    if cc < 3 && !visited[cr][cc + 1] && grid[cr][cc + 1] == 1 {
                        visited[cr][cc + 1] = true;
                        stack = stack + [cr * 4 + (cc + 1)];
                    }
                }
                sizes = sizes + [size];
            }
        }
    }

    let rowUse: Int[] = [0, 0, 0, 0];
    loop r in 0..4 {
        loop c in 0..4 {
            if grid[r][c] != 0 {
                rowUse[r] = rowUse[r] + 1;
            }
        }
    }

    let bestR: Int = 0;
    let bestC: Int = 0;
    let bestSum: Int = 0;
    loop r in 0..3 {
        loop c in 0..3 {
            let s: Int = grid[r][c] + grid[r][c + 1] + grid[r + 1][c] + grid[r + 1][c + 1];
            if grid[r][c] != 0 && grid[r][c + 1] != 0 && grid[r + 1][c] != 0 && grid[r + 1][c + 1] != 0 {
                if s > bestSum {
                    bestSum = s;
                    bestR = r;
                    bestC = c;
                }
            }
        }
    }

    fx {
        println("CLUSTERS ", length(sizes));
        let sizeStr: Text = "";
        loop i in 0..length(sizes) {
            if i > 0 {
                sizeStr = sizeStr + " ";
            }
            sizeStr = sizeStr + int_to_text(sizes[i]);
        }
        println("SIZES ", sizeStr);
        println("ROWUSE ", rowUse[0], " ", rowUse[1], " ", rowUse[2], " ", rowUse[3]);
        println("BESTBLOCK ", bestR, ",", bestC, " ", bestSum);
        println("EMPTY ", emptyCount);
    }
    ret;
}

