fn minCoins(amount: Int) -> Int {
    let coins: Int[] = [50, 25, 10, 5, 1];
    let count: Int = 0;
    loop d in coins {
        let q: Int = amount div d;
        count = count + q;
        amount = amount % d;
    }
    ret count;
}

