@pure
fn digitSum(n: Int) -> Int {
    let x: Int = n;
    loop x >= 10 {
        let s: Int = 0;
        let t: Int = x;
        loop t > 0 {
            s = s + t % 10;
            t = t div 10;
        }
        x = s;
    }
    ret x;
}

