@pure
fn checkLabel(label: Text) -> Text {
    if string_len(label) != 2 {
        ret "NOMATCH";
    }
    let first: Int = ord(label[0]);
    let second: Int = ord(label[1]);
    if first < 65 || first > 72 {
        ret "NOMATCH";
    }
    if second < 48 || second > 57 {
        ret "NOMATCH";
    }
    let letterPos: Int = first - 64;
    let digitVal: Int = second - 48;
    if letterPos == digitVal {
        ret "MATCH";
    }
    ret "NOMATCH";
}

