        loop j >= 0 {
            if points[order[j]] >= points[v] {
                break;
            }
            order[j + 1] = order[j];
            j = j - 1;
        }
        order[j + 1] = v;
    }

    fx {
        loop i in 0..n {
            let idx: Int = order[i];
            println(names[idx], ": ", points[idx]);
        }
    }
