        loop j in 0..length(uniqueArtists) {
            if uniqueArtists[j] == artists[i] {
                found = true;
                break;
            }
        }
        if !found {
            uniqueArtists = uniqueArtists + [artists[i]];
            counts = counts + [0];
        }
    }

    loop i in 0..length(artists) {
        loop j in 0..length(uniqueArtists) {
            if uniqueArtists[j] == artists[i] {
                counts[j] = counts[j] + 1;
                break;
            }
        }
    }

    let maxCount: Int = 0;
    loop i in 0..length(counts) {
        if counts[i] > maxCount {
            maxCount = counts[i];
        }
    }

    let tiedArtists: Text[] = [];
    loop i in 0..length(uniqueArtists) {
        if counts[i] == maxCount {
            tiedArtists = tiedArtists + [uniqueArtists[i]];
        }
    }

    let sortedArtists: Text[] = tiedArtists;
    loop i in 1..length(sortedArtists) {
        let v: Text = sortedArtists[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if sortedArtists[j] <= v {
                break;
            }
            sortedArtists[j + 1] = sortedArtists[j];
            j = j - 1;
        }
        sortedArtists[j + 1] = v;
    }

    loop i in 0..length(sortedArtists) {
        let idx: Int = 0;
        loop k in 0..length(uniqueArtists) {
            if uniqueArtists[k] == sortedArtists[i] {
                idx = k;
                break;
            }
        }
        fx {
            println(sortedArtists[i], ": ", counts[idx]);
        }
    }

    ret;
}

