        let c: Text = commands[i];
        if c == "F" {
            if dir == 0 {
                row = row - 1;
            } else if dir == 1 {
                col = col + 1;
            } else if dir == 2 {
                row = row + 1;
            } else {
                col = col - 1;
            }
            if row < 0 {
                row = 0;
            }
            if row > 4 {
                row = 4;
            }
            if col < 0 {
                col = 0;
            }
            if col > 4 {
                col = 4;
            }
        } else if c == "B" {
            if dir == 0 {
                row = row + 1;
            } else if dir == 1 {
                col = col - 1;
            } else if dir == 2 {
                row = row - 1;
            } else {
                col = col + 1;
            }
            if row < 0 {
                row = 0;
            }
            if row > 4 {
                row = 4;
            }
            if col < 0 {
                col = 0;
            }
            if col > 4 {
                col = 4;
            }
        } else if c == "L" {
            dir = (dir + 3) % 4;
        } else if c == "R" {
