@pure
fn countPaths(level: Int, target: Int, forbidden: Int) -> Int {
    if level == target {
        ret 1;
    }
    if level > target {
        ret 0;
    }
    let total: Int = 0;
    let next1: Int = level + 1;
    if next1 != forbidden {
        total = total + countPaths(next1, target, forbidden);
    }
    let next2: Int = level + 2;
    if next2 != forbidden {
        total = total + countPaths(next2, target, forbidden);
    }
    ret total;
}

