fn main() -> Void {
    let grid: Real[][] = [
        [120.0, 130.0, 140.0],
        [150.0, 160.0, 170.0],
        [180.0, 190.0, 200.0]
    ];

    let rows: Int = 3;
    let cols: Int = 3;

    loop r in 0..rows {
        loop c in 0..cols {
            let sum: Real = grid[r][c];
            let count: Int = 1;

            if r > 0 {
                sum = sum + grid[r - 1][c];
                count = count + 1;
            }
            if r < rows - 1 {
                sum = sum + grid[r + 1][c];
                count = count + 1;
            }
            if c > 0 {
                sum = sum + grid[r][c - 1];
                count = count + 1;
            }
            if c < cols - 1 {
                sum = sum + grid[r][c + 1];
                count = count + 1;
            }

            let avg: Real = sum / count;
            let val: Text = formatfloat(avg, 2);

            if c == 0 {
                fx { print(val); }
            } else {
                fx { print(" ", val); }
            }
        }
        fx { println(""); }
    }

    ret;
}

