        println("In range: ", inRange);
    }

    loop r in 0..3 {
        let rowMin: Int = grid[r][0];
        let rowMax: Int = grid[r][0];
        loop c in 1..3 {
            if grid[r][c] < rowMin {
                rowMin = grid[r][c];
            }
            if grid[r][c] > rowMax {
                rowMax = grid[r][c];
            }
        }
        fx {
            println("Row ", r + 1, ": min=", rowMin, " max=", rowMax);
        }
    }

    ret;
}

fn main() -> Void {
    let grid: Int[][] = [
        [1, 0, 1],
        [0, 1, 0],
        [1, 1, 0]
    ];
    let isolated: Int = 0;
    loop r in 0..3 {
        loop c in 0..3 {
            if grid[r][c] == 1 {
                let isIso: Bool = true;
                loop dr in -1..2 {
                    loop dc in -1..2 {
                        if dr == 0 && dc == 0 {
                            continue;
                        }
                        let nr: Int = r + dr;
                        let nc: Int = c + dc;
                        if nr >= 0 && nr < 3 && nc >= 0 && nc < 3 {
                            if grid[nr][nc] == 1 {
                                isIso = false;
                            }
                        }
                    }
                }
                if isIso {
                    isolated = isolated + 1;
                }
            }
        }
    }
    fx {
        println("Isolated leaks: ", isolated);
    }
    ret;
}

fn main() -> Void {
    let ratings: Int[] = [8, 6, 9, 7, 5, 10];
    let strongCount: Int = 0;
    let strongTotal: Int = 0;
    let weakCount: Int = 0;
    let weakTotal: Int = 0;

    loop r in ratings {
        if r >= 7 {
            strongCount = strongCount + 1;
            strongTotal = strongTotal + r;
        } else {
            weakCount = weakCount + 1;
            weakTotal = weakTotal + r;
        }
    }

    fx {
        println("Strong count: ", strongCount);
        println("Strong total: ", strongTotal);
        println("Weak count: ", weakCount);
        println("Weak total: ", weakTotal);
    }
    ret;
}
